package com.remapcamera;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class CameraKeyOverlay extends Overlay
{
	/** The space the client's overlay renderer keeps between the viewport and its top left overlays. */
	private static final int BORDER = 5;
	private static final int BORDER_TOP = BORDER + 15;

	private final Client client;
	private final RemapCameraPlugin plugin;
	private final RemapCameraConfig config;

	@Inject
	CameraKeyOverlay(Client client, RemapCameraPlugin plugin, RemapCameraConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;

		// Overlays in a layer are ordered by their position before their priority, so any overlay
		// with a fixed position is drawn after a dynamic one and would hide the text; the escape
		// crystal widget, for example, sits at BOTTOM_LEFT. TOOLTIP is the last position in that
		// order and, like DYNAMIC, is drawn where the plugin says instead of in a snap corner
		// stack, so the text stays on top and stays where it was configured.
		setPosition(OverlayPosition.TOOLTIP);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.cameraKeysEnabled() || !config.keyIndicatorEnabled() || !plugin.cameraKeysHeld())
		{
			return null;
		}

		String text = config.indicatorText();

		if (text.isEmpty())
		{
			return null;
		}

		Point topLeft = topLeft();
		int x = topLeft.x + config.indicatorX();
		int y = topLeft.y + config.indicatorY() + chatboxOffset();

		graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, config.indicatorSize()));
		FontMetrics metrics = graphics.getFontMetrics();
		int baseline = y + metrics.getAscent();

		graphics.setColor(Color.BLACK);

		for (int offsetX = -1; offsetX <= 1; offsetX++)
		{
			for (int offsetY = -1; offsetY <= 1; offsetY++)
			{
				if (offsetX != 0 || offsetY != 0)
				{
					graphics.drawString(text, x + offsetX, baseline + offsetY);
				}
			}
		}

		graphics.setColor(config.indicatorColor());
		graphics.drawString(text, x, baseline);

		return new Dimension(x + metrics.stringWidth(text) + 2, y + metrics.getHeight());
	}

	private int chatboxOffset()
	{
		if (!config.indicatorRespectChatbox())
		{
			return 0;
		}

		Widget chatbox = client.getWidget(InterfaceID.Chatbox.CHATAREA);

		return chatbox == null || chatbox.isHidden() ? 0 : config.indicatorChatboxY();
	}

	/**
	 * The place the client starts its stack of top left overlays (the margins and viewport widget of
	 * {@code OverlayRenderer.positionSnapcorners}), so the indicator keeps the spot it was configured
	 * for. It is not part of that stack itself: another top left overlay, such as the opponent info of
	 * a fight, would otherwise push it down until that overlay disappears again.
	 */
	private Point topLeft()
	{
		Widget viewport = viewportLayer();
		Rectangle bounds = viewport != null ? viewport.getBounds() : new Rectangle();

		return new Point(bounds.x + BORDER, bounds.y + BORDER_TOP);
	}

	/** The widget the client anchors its top left overlays at, the same one it uses itself. */
	private Widget viewportLayer()
	{
		if (client.isResized())
		{
			if (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1)
			{
				return client.getWidget(InterfaceID.ToplevelPreEoc.HUD_CONTAINER_FRONT);
			}

			return client.getWidget(InterfaceID.ToplevelOsrsStretch.HUD_CONTAINER_FRONT);
		}

		return client.getWidget(InterfaceID.Toplevel.OVERLAY_HUD);
	}
}

package com.remapcamera;

/**
 * A mouse button that can hold the free look camera.
 *
 * <p>Only extra buttons are offered. The left and right button belong to the game, and the middle
 * button already rotates the camera itself, so using it here would rotate twice.
 *
 * <p>The enum is public because it is a config item type: the config RuneLite hands to the plugin is
 * a dynamic proxy, and a proxy cannot return a type it cannot access.
 */
public enum CameraRotateMouseButton
{
	OFF("Off", 0),
	BUTTON_4("Mouse button 4", 4),
	BUTTON_5("Mouse button 5", 5);

	/** MouseEvent has no constants for buttons past BUTTON3. */
	private static final int FIRST_EXTRA_BUTTON = 4;

	private final String name;
	private final int button;

	CameraRotateMouseButton(String name, int button)
	{
		this.name = name;
		this.button = button;
	}

	/**
	 * Whether the pressed button is the one this option names. Left click, the middle button and
	 * right click never match, whatever the option is set to.
	 */
	boolean matches(int pressedButton)
	{
		return button >= FIRST_EXTRA_BUTTON && pressedButton == button;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.remapcamera;

/**
 * Keeps the arrow key camera at a fraction of the movement the client makes.
 *
 * <p>The keys are not blocked: the client keeps receiving and acting on them, and the movement it
 * made since the previous frame is scaled here. That matters because the game uses that same input
 * to decide whether the player is active, which an escape crystal's inactivity timer relies on.
 *
 * <p>Nothing is derived from a fixed number of units per second: the client moves the camera along
 * its own acceleration curve, so the measured movement is the only truth. A fraction that is left
 * over is kept for the next frame, so even a speed far below one camera unit per frame still moves
 * the camera.
 *
 * <p>The compass sets an absolute target instead of moving the camera like a key does, so it is
 * passed through untouched: one click still has to point the camera north, whatever the configured
 * speed.
 */
class CameraSpeed
{
	private static final int YAW_UNITS = 16384;
	private static final int PITCH_MIN = 1024;
	private static final int PITCH_MAX = 3064;

	private int yaw = -1;
	private int pitch;
	private double yawRemainder;
	private double pitchRemainder;

	/** The target the client should get, after {@link #update}. */
	int yaw()
	{
		return yaw;
	}

	int pitch()
	{
		return pitch;
	}

	/** Forgets the camera position, so that the next frame takes it over again. */
	void reset()
	{
		yaw = -1;
		yawRemainder = 0;
		pitchRemainder = 0;
	}

	/** Remembers a target that was written without the plugin scaling it. */
	void written(int yawTarget, int pitchTarget)
	{
		yaw = yawTarget;
		pitch = pitchTarget;
	}

	/**
	 * Scales the movement the client made since the previous frame.
	 *
	 * @param yawTarget          the camera target the client currently has
	 * @param pitchTarget        the camera target the client currently has
	 * @param speed              the configured fraction of the client's keyboard camera speed
	 * @param clientDrivesCamera the client is moving the camera from the mouse, so its target is the
	 *                           truth and nothing may be scaled
	 * @param holdCamera         the camera is being rotated with the rotate key, so only that
	 *                           rotation may move the camera
	 * @param compassClick       the compass was clicked, which sets an absolute target that must
	 *                           not be scaled, or it would take several clicks to point north
	 */
	void update(int yawTarget, int pitchTarget, double speed, boolean clientDrivesCamera,
		boolean holdCamera, boolean compassClick)
	{
		if (yaw < 0 || clientDrivesCamera)
		{
			yawRemainder = 0;
			pitchRemainder = 0;
			written(yawTarget, pitchTarget);

			return;
		}

		if (holdCamera)
		{
			yawRemainder = 0;
			pitchRemainder = 0;

			if (compassClick)
			{
				yaw = yawTarget & (YAW_UNITS - 1);
			}

			return;
		}

		if (compassClick)
		{
			yawRemainder = 0;
			yaw = yawTarget & (YAW_UNITS - 1);
		}
		else
		{
			int yawDelta = shortestRotation(yaw, yawTarget);

			yaw = (yaw + scaled(yawDelta, speed, true)) & (YAW_UNITS - 1);
		}

		int pitchDelta = pitchTarget - pitch;

		pitch = clamp(pitch + scaled(pitchDelta, speed, false));
	}

	/**
	 * The part of a movement that is kept. A single frame can be smaller than one camera unit, so
	 * the remainder is carried to the next frame instead of being rounded away.
	 */
	private int scaled(int delta, double speed, boolean yawAxis)
	{
		double remainder = yawAxis ? yawRemainder : pitchRemainder;
		double value = delta * speed + remainder;
		int step = (int) value;

		if (yawAxis)
		{
			yawRemainder = value - step;
		}
		else
		{
			pitchRemainder = value - step;
		}

		return step;
	}

	private static int clamp(int pitch)
	{
		return Math.max(PITCH_MIN, Math.min(PITCH_MAX, pitch));
	}

	private static int shortestRotation(int from, int to)
	{
		int delta = (to - from) % YAW_UNITS;

		if (delta > YAW_UNITS / 2)
		{
			delta -= YAW_UNITS;
		}
		else if (delta < -YAW_UNITS / 2)
		{
			delta += YAW_UNITS;
		}

		return delta;
	}
}

package com.remapcamera;

import java.awt.Color;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.ModifierlessKeybind;

@ConfigGroup("remapCamera")
public interface RemapCameraConfig extends Config
{
	@ConfigSection(
			name = "Free look camera",
			description = "Settings for remapping the free look camera",
			position = 0
	)
	String cameraSection = "camera";

	@ConfigItem(
			position = 1,
			keyName = "cameraRotateRemap",
			name = "Remap camera rotating key",
			description = "When enabled, holding the camera rotating key and moving the mouse will rotate the camera.",
			section = cameraSection
	)
	default boolean cameraRotateRemap()
	{
		return false;
	}

	@ConfigItem(
			position = 2,
			keyName = "cameraRotateKey",
			name = "Camera rotating key",
			description = "Hold this key while moving the mouse to rotate the camera.",
			section = cameraSection
	)
	default ModifierlessKeybind cameraRotateKey()
	{
		return new ModifierlessKeybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
			position = 3,
			keyName = "invertCamera",
			name = "Invert camera",
			description = "Inverts the camera rotation direction. Enable this if the camera moves the wrong way.",
			section = cameraSection
	)
	default boolean invertCamera()
	{
		return false;
	}

	@ConfigItem(
			position = 4,
			keyName = "respectDialogues",
			name = "Respect dialogues",
			description = "The plugin will respect dialogues and not run when a dialogue or interface is open.",
			section = cameraSection
	)
	default boolean respectDialogues()
	{
		return false;
	}

	@Range(min = 1, max = 10000)
	@ConfigItem(
			position = 5,
			keyName = "sensitivity",
			name = "Camera sensitivity",
			description = "Mouse sensitivity when rotating the camera. Default is 1440 which is around the same as middle mouse click camera rotation.",
			section = cameraSection
	)
	default int sensitivity()
	{
		return 1440;
	}

	@ConfigItem(
			position = 6,
			keyName = "cameraRotateMouseButton",
			name = "Camera rotating mouse button",
			description = "Rotate the camera while this mouse button is held, as an alternative to the " +
					"camera rotating key.",
			section = cameraSection
	)
	default CameraRotateMouseButton cameraRotateMouseButton()
	{
		return CameraRotateMouseButton.OFF;
	}

	@ConfigSection(
			name = "Camera keys",
			description = "Settings for the arrow key camera. Nothing below does anything while it is off.",
			position = 1,
			closedByDefault = true
	)
	String cameraKeysSection = "cameraKeys";

	@ConfigItem(
			position = 1,
			keyName = "cameraKeysEnabled",
			name = "Use camera key configuration",
			description = "Enables everything below it. While it is off the plugin does not touch the " +
					"arrow key camera at all and only the free look camera of the section above is used.",
			section = cameraKeysSection
	)
	default boolean cameraKeysEnabled()
	{
		return false;
	}

	@Range(min = 0, max = 20)
	@ConfigItem(
			position = 2,
			keyName = "cameraSpeed",
			name = "Camera key speed",
			description = "Speed of the arrow key camera as a fraction of the normal speed: 1 = normal",
			section = cameraKeysSection
	)
	default double cameraSpeed()
	{
		return 1;
	}

	@ConfigItem(
			position = 3,
			keyName = "keyIndicatorEnabled",
			name = "Show camera key indicator",
			description = "Shows the indicator while a camera key is held.",
			section = cameraKeysSection
	)
	default boolean keyIndicatorEnabled()
	{
		return false;
	}

	@ConfigItem(
			position = 4,
			keyName = "indicatorText",
			name = "Indicator text",
			description = "The text of the indicator, for example a check mark.",
			section = cameraKeysSection
	)
	default String indicatorText()
	{
		return "✓";
	}

	@Alpha
	@ConfigItem(
			position = 5,
			keyName = "indicatorColor",
			name = "Indicator color",
			description = "Colour of the indicator text.",
			section = cameraKeysSection
	)
	default Color indicatorColor()
	{
		return Color.GREEN;
	}

	@Range(min = 8, max = 128)
	@ConfigItem(
			position = 6,
			keyName = "indicatorSize",
			name = "Indicator size",
			description = "Font size of the indicator text.",
			section = cameraKeysSection
	)
	default int indicatorSize()
	{
		return 16;
	}

	@Range(min = -1000, max = 1000)
	@ConfigItem(
			position = 7,
			keyName = "indicatorX",
			name = "Indicator X offset",
			description = "Horizontal offset from the top left of the game viewport, in pixels.",
			section = cameraKeysSection
	)
	default int indicatorX()
	{
		return 0;
	}

	@Range(min = -1000, max = 1000)
	@ConfigItem(
			position = 8,
			keyName = "indicatorY",
			name = "Indicator Y offset",
			description = "Vertical offset from the top left of the game viewport, in pixels.",
			section = cameraKeysSection
	)
	default int indicatorY()
	{
		return 0;
	}

	@ConfigItem(
			position = 9,
			keyName = "indicatorRespectChatbox",
			name = "Respect chatbox",
			description = "Moves the indicator while the chatbox is open, because the game moves its " +
					"own overlays then too. Use the offset below to set how far.",
			section = cameraKeysSection
	)
	default boolean indicatorRespectChatbox()
	{
		return false;
	}

	@Range(min = -1000, max = 1000)
	@ConfigItem(
			position = 10,
			keyName = "indicatorChatboxY",
			name = "Chatbox Y offset",
			description = "How many pixels the indicator moves while the chatbox is open. A negative " +
					"number moves it up.",
			section = cameraKeysSection
	)
	default int indicatorChatboxY()
	{
		return 0;
	}
}

package com.remapcamera;

import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class RemapCameraListener implements KeyListener, MouseListener
{
	private static final Logger log = LoggerFactory.getLogger(RemapCameraListener.class);

	/** The compass of every top level layout; only the one of the current layout exists. */
	private static final int[] COMPASS_WIDGETS =
	{
		InterfaceID.ToplevelOsrsStretch.COMPASSCLICK,
		InterfaceID.ToplevelPreEoc.COMPASSCLICK,
		InterfaceID.Toplevel.COMPASSCLICK,
		InterfaceID.ToplevelOsm.COMPASSCLICK
	};

	/** How long the target the compass sets is left alone, so it is never missed. */
	private static final long COMPASS_CLICK_WINDOW_MS = 200;

	@Inject
	private Client client;
	@Inject
	private RemapCameraConfig config;
	@Inject
	private RemapCameraPlugin plugin;

	private volatile boolean cameraRotateKeyPressed = false;
	private volatile boolean cameraRotateButtonPressed = false;

	/**
	 * The camera keys that are currently held. They are tracked here, on the listener the client
	 * hands its key events to, and never by hooking the keyboard of the whole application.
	 */
	private final Set<Integer> heldKeys = ConcurrentHashMap.newKeySet();

	private volatile long compassClickUntil;

	/** Whether the free look camera should rotate, by the configured key or by the mouse button. */
	boolean isCameraRotateHeld()
	{
		return cameraRotateKeyPressed || cameraRotateButtonPressed;
	}

	boolean isCameraRotateKeyHeld()
	{
		return cameraRotateKeyPressed;
	}

	boolean isCameraRotateButtonHeld()
	{
		return cameraRotateButtonPressed;
	}

	boolean isCameraKeyHeld()
	{
		return !heldKeys.isEmpty();
	}

	/**
	 * Whether the compass was clicked just now. The compass sets the camera target to an absolute
	 * angle instead of moving it like a key does, so the target has to be left alone right after
	 * the click; scaling it would make the camera turn only part of the way to north.
	 */
	boolean isCompassClickActive()
	{
		return System.nanoTime() < compassClickUntil;
	}

	/** Starts the window in which the target the compass sets is not scaled. */
	void compassClicked()
	{
		compassClickUntil = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(COMPASS_CLICK_WINDOW_MS);
	}

	/** Forgets every key, because their release is delivered to whichever window gets the focus. */
	void reset()
	{
		heldKeys.clear();
		resetRotation();
		compassClickUntil = 0;
	}

	/**
	 * Forgets the rotation only. The configured key or button can change while one of them is held,
	 * and its release would then never be recognised.
	 */
	void resetRotation()
	{
		if (cameraRotateKeyPressed || cameraRotateButtonPressed)
		{
			log.debug("forgetting rotation (key {} / button {})", cameraRotateKeyPressed, cameraRotateButtonPressed);
		}

		cameraRotateKeyPressed = false;
		cameraRotateButtonPressed = false;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!plugin.isTyping() && isCameraKey(e.getKeyCode()))
		{
			heldKeys.add(e.getKeyCode());
		}

		if (config.cameraRotateRemap() && config.cameraRotateKey().matches(e))
		{
			// A held key repeats this event, so only the first press is worth a log line.
			boolean firstPress = !cameraRotateKeyPressed;

			if (config.respectDialogues() && plugin.isDialogOpen())
			{
				if (firstPress)
				{
					log.debug("rotation key {} pressed but a dialogue is open", KeyEvent.getKeyText(e.getKeyCode()));
				}

				return;
			}

			// Observe only, so the event is not consumed: the client keeps its own key state either
			// way, and consuming would only take the key's activity away from the game.
			if (firstPress)
			{
				log.debug("rotation key {} held", KeyEvent.getKeyText(e.getKeyCode()));
			}

			cameraRotateKeyPressed = true;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		heldKeys.remove(e.getKeyCode());

		if (config.cameraRotateRemap() && cameraRotateKeyPressed && config.cameraRotateKey().matches(e))
		{
			cameraRotateKeyPressed = false;
			log.debug("rotation key {} released", KeyEvent.getKeyText(e.getKeyCode()));
		}
	}

	@Override
	public void focusLost()
	{
		log.debug("focus lost, forgetting every held key");
		reset();
	}

	private static boolean isCameraKey(int keyCode)
	{
		return keyCode == KeyEvent.VK_UP || keyCode == KeyEvent.VK_DOWN
			|| keyCode == KeyEvent.VK_LEFT || keyCode == KeyEvent.VK_RIGHT;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (isCompassClick(e.getX(), e.getY()))
		{
			compassClicked();
		}

		CameraRotateMouseButton configured = config.cameraRotateMouseButton();
		boolean match = configured.matches(e.getButton());
		boolean dialogueBlocks = config.respectDialogues() && plugin.isDialogOpen();

		if (match && !dialogueBlocks)
		{
			// The event is left as it is: nothing is consumed and no button is rewritten, so the
			// game sees exactly the click it would see without the plugin.
			cameraRotateButtonPressed = true;
		}

		log.debug("mouse button {} pressed: option {}, match {}, dialogue blocks {}, consumed {}",
			e.getButton(), configured, match, dialogueBlocks, e.isConsumed());

		return e;
	}

	private boolean isCompassClick(int x, int y)
	{
		for (int widgetId : COMPASS_WIDGETS)
		{
			Widget compass = client.getWidget(widgetId);

			if (compass != null && compass.getBounds().contains(x, y))
			{
				return true;
			}
		}

		return false;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		boolean match = config.cameraRotateMouseButton().matches(e.getButton());

		if (match)
		{
			cameraRotateButtonPressed = false;
		}

		log.debug("mouse button {} released: match {}, consumed {}", e.getButton(), match, e.isConsumed());

		return e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		return e;
	}
}

package com.remapcamera;

import com.google.inject.Provides;
import java.awt.MouseInfo;
import java.awt.Point;
import java.awt.PointerInfo;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
		name = "Remap Camera Rotation",
		description = "Rotate the camera by holding a configurable key and moving the mouse, and" +
			" adjust the speed of the arrow key camera",
		tags = {"camera", "rotate", "speed", "remap"}
)
public class RemapCameraPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(RemapCameraPlugin.class);

	/** How often a running rotation writes a line to the debug log. */
	private static final long ROTATION_LOG_INTERVAL_MS = 1000;

	private static final int YAW_UNITS = 16384;
	private static final int PITCH_MIN = 1024;
	private static final int PITCH_MAX = 3064;
	private static final double MAX_SPEED = 20;

	/** Used to mirror the camera mouse button mask of the built-in Camera plugin. */
	private static final String CAMERA_CONFIG_GROUP = "camera";

	private static final int CAMERA_MOUSE_BUTTONS =
		(1 << MouseEvent.BUTTON2) | (1 << 4 /* the middle mouse button of the client */);

	private static final String CONFIG_GROUP =
		RemapCameraConfig.class.getAnnotation(ConfigGroup.class).value();

	/** The menu option of the compass, which is the only menu entry that has it. */
	private static final String COMPASS_MENU_OPTION = "Look North";

	@Inject
	private Client client;

	@Inject
	private KeyManager keyManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RemapCameraConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private RemapCameraListener inputListener;

	@Inject
	private CameraKeyOverlay keyOverlay;

	private final CameraSpeed cameraSpeed = new CameraSpeed();

	private Point lastMousePosition;

	private net.runelite.api.Point lastCanvasMouse;

	/** The rotation state of the previous frame, so a start or stop is logged only once. */
	private boolean lastRotating;

	/** Whether the front place of the mouse listeners has been claimed after the client started. */
	private boolean inputListenerInFront;

	private long lastRotationLog;

	@Override
	protected void startUp() throws Exception
	{
		mouseManager.registerMouseListener(0, inputListener);
		keyManager.registerKeyListener(inputListener);
		overlayManager.add(keyOverlay);
		lastMousePosition = null;
		lastRotating = false;
		inputListenerInFront = false;
		lastRotationLog = 0;

		log.debug("started: rotate key {}, rotate button {}, camera keys {}",
			config.cameraRotateKey(), config.cameraRotateMouseButton(), config.cameraKeysEnabled());
	}

	@Override
	protected void shutDown() throws Exception
	{
		keyManager.unregisterKeyListener(inputListener);
		mouseManager.unregisterMouseListener(inputListener);
		overlayManager.remove(keyOverlay);
		lastMousePosition = null;

		// The release of a key that is held while the plugin is turned off is never seen, so it
		// would otherwise stay held for the indicator.
		inputListener.reset();
		log.debug("stopped");
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		claimFrontMouseListener();

		boolean rotateHeld = inputListener.isCameraRotateHeld();
		boolean rotating = rotateHeld && !isDialogOpen();
		boolean scaleKeys = config.cameraKeysEnabled();

		if (rotating != lastRotating)
		{
			lastRotating = rotating;
			lastRotationLog = 0;

			log.debug("rotation {}: rotate key {}, rotate button {}, dialogue open {}",
				rotating ? "started" : "stopped", inputListener.isCameraRotateKeyHeld(),
				inputListener.isCameraRotateButtonHeld(), rotateHeld && !rotating);
		}

		if (!scaleKeys)
		{
			// With the camera key configuration off the plugin behaves like it did before those
			// options existed: the arrow keys are left to the client and only the rotation is written.
			cameraSpeed.reset();

			if (!rotating)
			{
				lastMousePosition = null;

				return;
			}
		}

		int yaw = client.getCameraYawTarget();
		int pitch = client.getCameraPitchTarget();

		if (scaleKeys)
		{
			// The arrow keys are scaled, not blocked, so the game keeps seeing them as input. While
			// the camera is rotated, and while the client is dragging its own camera with the mouse,
			// only that rotation may move the camera.
			boolean mouseMoved = mouseMoved();
			boolean clientDrivesCamera = clientCameraDrag()
				&& (mouseMoved || !inputListener.isCameraKeyHeld());

			cameraSpeed.update(yaw, pitch, cameraSpeed(), clientDrivesCamera,
				rotating && !clientDrivesCamera, inputListener.isCompassClickActive());
			yaw = cameraSpeed.yaw();
			pitch = cameraSpeed.pitch();
		}

		if (!rotating)
		{
			lastMousePosition = null;
		}
		else
		{
			PointerInfo pointerInfo = MouseInfo.getPointerInfo();
			Point currentPos = pointerInfo != null ? pointerInfo.getLocation() : null;

			if (currentPos != null)
			{
				if (lastMousePosition != null)
				{
					int dx = currentPos.x - lastMousePosition.x;
					int dy = currentPos.y - lastMousePosition.y;

					if (dx != 0 || dy != 0)
					{
						double scale = config.sensitivity() / 100.0;
						dx = (int) Math.round(dx * scale);
						dy = (int) Math.round(dy * scale);
						if (config.invertCamera())
						{
							dx = -dx;
							dy = -dy;
						}

						yaw = (yaw + dx) & (YAW_UNITS - 1);
						pitch = Math.max(PITCH_MIN, Math.min(PITCH_MAX, pitch - dy));

						logRotation(dx, dy, yaw, pitch);
					}
				}

				lastMousePosition = currentPos;
			}
		}

		client.setCameraYawTarget(yaw);
		client.setCameraPitchTarget(pitch);

		if (scaleKeys)
		{
			cameraSpeed.written(yaw, pitch);
		}
	}

	/**
	 * The compass is also seen here, because its bounds and the mouse position do not have to be in
	 * the same space when the game is stretched. Only the compass has this menu option.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (COMPASS_MENU_OPTION.equals(event.getMenuOption()))
		{
			inputListener.compassClicked();
		}
	}

	/**
	 * Respecting dialogues already means the plugin follows the interface state of the game, so the
	 * indicator has to follow the chatbox too. Turning the option back off does not turn this off
	 * again, so a manual choice keeps standing.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		// The key or button that is held can be reconfigured while it is down, and its release
		// would then no longer match.
		inputListener.resetRotation();
		log.debug("config {} changed to {}", event.getKey(), event.getNewValue());

		if ("respectDialogues".equals(event.getKey())
			&& Boolean.parseBoolean(event.getNewValue())
			&& !config.indicatorRespectChatbox())
		{
			configManager.setConfiguration(CONFIG_GROUP, "indicatorRespectChatbox", true);
		}
	}

	/**
	 * Puts the input listener in front of the mouse listeners once, after the client has started.
	 *
	 * <p>RuneLite consumes a press of a mouse button past the middle one before it walks its mouse
	 * listeners, and that walk stops at the first listener it hands the consumed event, so such a
	 * press only reaches the first registered listener. A plugin that claims the front place during
	 * its own startup (the built-in stretched mode plugin does) would push this listener back, so
	 * the place is claimed again on the first frame, when every plugin has started.
	 */
	private void claimFrontMouseListener()
	{
		if (inputListenerInFront)
		{
			return;
		}

		mouseManager.unregisterMouseListener(inputListener);
		mouseManager.registerMouseListener(0, inputListener);
		inputListenerInFront = true;

		log.debug("input listener is in front of the mouse listeners");
	}

	/** Writes at most one line per second, so the log of a running rotation stays readable. */
	private void logRotation(int dx, int dy, int yaw, int pitch)
	{
		long now = System.currentTimeMillis();

		if (!log.isDebugEnabled() || now - lastRotationLog < ROTATION_LOG_INTERVAL_MS)
		{
			return;
		}

		lastRotationLog = now;
		log.debug("rotating: dx {}, dy {}, yaw {}, pitch {}", dx, dy, yaw, pitch);
	}

	/** The configured camera key speed, clamped to the range the config allows. */
	private double cameraSpeed()
	{
		double speed = config.cameraSpeed();

		if (!(speed > 0))
		{
			return 0;
		}

		return Math.min(speed, MAX_SPEED);
	}

	/** The client moves its camera from the mouse alone while a camera mouse button is held. */
	private boolean clientCameraDrag()
	{
		return isCameraDrag(cameraMask(), client.getMouseCurrentButton());
	}

	/**
	 * The decision the client itself makes: with a mask, the bit of the button it sees; without one
	 * only its own extra mouse button. The button it sees is not the button that was pressed when the
	 * built-in Camera plugin rewrote a right click into a middle click, so the mask has to be taken
	 * into account to tell a camera drag from keyboard movement.
	 */
	static boolean isCameraDrag(int mask, int button)
	{
		if (button < 0 || button > 30)
		{
			return false;
		}

		if (mask != 0)
		{
			return ((mask >> button) & 1) != 0;
		}

		return button == 4;
	}

	/**
	 * The camera mouse button mask the built-in Camera plugin gives the client, mirroring that
	 * plugin's own config. It decides whether the client moves its camera from the mouse or from the
	 * keys, so the two have to agree.
	 */
	private int cameraMask()
	{
		return cameraMask(
			configManager.getConfiguration(CAMERA_CONFIG_GROUP, "rightClickMovesCamera", Boolean.class),
			configManager.getConfiguration(CAMERA_CONFIG_GROUP, "rightClickMenuBlocksCamera", Boolean.class));
	}

	static int cameraMask(Boolean rightClickMovesCamera, Boolean rightClickMenuBlocksCamera)
	{
		boolean movesCamera = rightClickMovesCamera != null && rightClickMovesCamera;
		boolean menuBlocks = rightClickMenuBlocksCamera == null || rightClickMenuBlocksCamera;

		return movesCamera && !menuBlocks ? CAMERA_MOUSE_BUTTONS : 0;
	}

	/**
	 * Whether the mouse moved since the previous frame. A camera drag needs mouse movement, so a
	 * movement of the camera while the mouse is still cannot come from the mouse.
	 */
	private boolean mouseMoved()
	{
		net.runelite.api.Point position = client.getMouseCanvasPosition();
		boolean moved = lastCanvasMouse == null || !lastCanvasMouse.equals(position);
		lastCanvasMouse = position;

		return moved;
	}

	/** Whether the plugin currently sees a camera key, for the info overlay. */
	boolean cameraKeysHeld()
	{
		return inputListener.isCameraKeyHeld();
	}

	/** Whether the player is typing in the chatbox or another text field of the client. */
	boolean isTyping()
	{
		return client.getFocusedInputFieldWidget() != null;
	}

	/**
	 * Check if a dialog is open that will grab numerical input, to prevent F-key remapping
	 * from triggering.
	 */
	public boolean isDialogOpen()
	{
		// Most chat dialogs with numerical input are added without the chatbox or its key listener being removed,
		// so chatboxFocused() is true. The chatbox onkey script uses the following logic to ignore key presses,
		// so we will use it too to not remap keys.
		return isHidden(InterfaceID.Chatbox.MES_LAYER_HIDE) || isHidden(InterfaceID.Chatbox.CHATDISPLAY)
				// We want to block camera remapping in the bank pin interface too, so it does not interfere with the
				// Keyboard Bankpin feature of the Bank plugin
				|| !isHidden(InterfaceID.BankpinKeypad.UNIVERSE);
	}

	private boolean isHidden(int component)
	{
		Widget w = client.getWidget(component);
		return w == null || w.isSelfHidden();
	}

	@Provides
	RemapCameraConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RemapCameraConfig.class);
	}
}

package com.remapcamera;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CameraMaskTest
{
	@Test
	public void theMaskMatchesWhatTheCameraPluginGivesTheClient()
	{
		// Right-click moves camera, and the menu does not block it: the client rotates with the
		// middle mouse button of the client, its own extra button, and the right click it rewrites
		// into a middle click.
		assertEquals((1 << 2) | (1 << 4), RemapCameraPlugin.cameraMask(true, false));
	}

	@Test
	public void withoutThatOptionTheClientHasNoMask()
	{
		assertEquals(0, RemapCameraPlugin.cameraMask(false, false));
		assertEquals(0, RemapCameraPlugin.cameraMask(null, null));
	}

	@Test
	public void aBlockingMenuTakesTheMaskAway()
	{
		// The Camera plugin still rewrites the right click into a middle click, but the client is
		// then on its keyboard path. That is the case the camera keys used to run away in.
		assertEquals(0, RemapCameraPlugin.cameraMask(true, true));
		assertEquals(0, RemapCameraPlugin.cameraMask(true, null));
	}

	@Test
	public void aRewrittenRightClickIsNotACameraDragWithoutTheMask()
	{
		assertFalse(RemapCameraPlugin.isCameraDrag(0, 2));
		assertFalse(RemapCameraPlugin.isCameraDrag(0, 3));
		assertTrue(RemapCameraPlugin.isCameraDrag(0, 4));
	}

	@Test
	public void withTheMaskOnlyTheButtonsOfTheMaskAreACameraDrag()
	{
		int mask = RemapCameraPlugin.cameraMask(true, false);

		assertTrue(RemapCameraPlugin.isCameraDrag(mask, 2));
		assertTrue(RemapCameraPlugin.isCameraDrag(mask, 4));
		assertFalse(RemapCameraPlugin.isCameraDrag(mask, 3));
	}

	@Test
	public void aimpossibleButtonIsNeverACameraDrag()
	{
		assertFalse(RemapCameraPlugin.isCameraDrag(-1, -1));
		assertFalse(RemapCameraPlugin.isCameraDrag(-1, 31));
	}
}

package com.remapcamera;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Proxy;
import org.junit.Test;

public class CameraRotateMouseButtonTest
{
	@Test
	public void onlyTheConfiguredExtraButtonMatches()
	{
		assertTrue(CameraRotateMouseButton.BUTTON_4.matches(4));
		assertTrue(CameraRotateMouseButton.BUTTON_5.matches(5));

		assertFalse(CameraRotateMouseButton.BUTTON_4.matches(5));
		assertFalse(CameraRotateMouseButton.BUTTON_5.matches(4));
	}

	@Test
	public void theButtonsOfTheGameNeverMatch()
	{
		for (CameraRotateMouseButton option : CameraRotateMouseButton.values())
		{
			assertFalse(option.matches(0));
			assertFalse(option.matches(1));
			assertFalse(option.matches(2));
			assertFalse(option.matches(3));
		}
	}

	@Test
	public void offMatchesNothing()
	{
		assertFalse(CameraRotateMouseButton.OFF.matches(4));
		assertFalse(CameraRotateMouseButton.OFF.matches(5));
	}

	/**
	 * RuneLite hands the plugin a dynamic proxy for the config interface, and that proxy class lives
	 * in its own package. A config item type it cannot access throws an IllegalAccessError on every
	 * call, which is why the enum has to be public.
	 */
	@Test
	public void theConfigProxyReturnsTheOption()
	{
		RemapCameraConfig config = (RemapCameraConfig) Proxy.newProxyInstance(
			RemapCameraConfig.class.getClassLoader(),
			new Class<?>[]
			{
				RemapCameraConfig.class
			},
			(proxy, method, args) -> CameraRotateMouseButton.BUTTON_5);

		assertSame(CameraRotateMouseButton.BUTTON_5, config.cameraRotateMouseButton());
	}
}

package com.remapcamera;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class CameraSpeedTest
{
	private static final int PITCH = 2048;

	private final CameraSpeed speed = new CameraSpeed();
	private int yaw = 1000;
	private int pitch = PITCH;

	/** One frame in which the client moved the camera by {@code movement}. */
	private void frame(int movement, double scale)
	{
		frame(movement, scale, false, false, false);
	}

	private void frame(int movement, double scale, boolean clientDrivesCamera, boolean holdCamera)
	{
		frame(movement, scale, clientDrivesCamera, holdCamera, false);
	}

	private void frame(int movement, double scale, boolean clientDrivesCamera, boolean holdCamera,
		boolean compassClick)
	{
		yaw += movement;
		speed.update(yaw, pitch, scale, clientDrivesCamera, holdCamera, compassClick);
		yaw = speed.yaw();
		pitch = speed.pitch();
	}

	@Test
	public void theFirstFrameTakesTheCameraPosition()
	{
		speed.update(1234, PITCH, 0.5, false, false, false);

		assertEquals(1234, speed.yaw());
		assertEquals(PITCH, speed.pitch());
	}

	@Test
	public void aResetTakesTheCameraPositionAgain()
	{
		frame(0, 0.1);

		for (int i = 0; i < 20; i++)
		{
			frame(24, 0.1);
		}

		speed.reset();
		speed.update(yaw, pitch, 0, false, false, false);

		assertEquals(yaw, speed.yaw());
	}

	@Test
	public void fullSpeedFollowsTheClient()
	{
		frame(0, 1);

		for (int i = 0; i < 20; i++)
		{
			frame(24, 1);
		}

		assertEquals(1000 + 20 * 24, yaw);
	}

	@Test
	public void zeroSpeedHoldsTheCamera()
	{
		frame(0, 0);

		for (int i = 0; i < 20; i++)
		{
			frame(24, 0);
		}

		assertEquals(1000, yaw);
	}

	@Test
	public void halfSpeedKeepsHalfOfTheMovement()
	{
		frame(0, 0.5);

		for (int i = 0; i < 20; i++)
		{
			frame(24, 0.5);
		}

		assertEquals(1000 + 20 * 12, yaw);
	}

	@Test
	public void theRemainderIsKeptForTheNextFrame()
	{
		frame(0, 0.1);

		// 24 * 0.1 is 2.4 units, so every frame has to keep a fraction instead of rounding it away.
		for (int i = 0; i < 10; i++)
		{
			frame(24, 0.1);
		}

		assertEquals(1000 + 24, yaw);
	}

	@Test
	public void theCameraStaysPutWhileTheCameraIsRotated()
	{
		frame(0, 0.5);

		for (int i = 0; i < 20; i++)
		{
			frame(24, 0.5);
		}

		int held = yaw;

		for (int i = 0; i < 10; i++)
		{
			frame(24, 0.5, false, true);
		}

		assertEquals(held, yaw);
	}

	@Test
	public void theMouseCameraIsNeverScaled()
	{
		frame(0, 0);

		frame(400, 0, true, false);

		assertEquals(1000 + 400, yaw);
	}

	@Test
	public void theCompassIsNeverScaled()
	{
		frame(0, 0.4);

		frame(-2000, 0.4, false, false, true);

		assertEquals((1000 - 2000) & 0x3FFF, yaw);
	}

	@Test
	public void theCompassWorksAtZeroSpeed()
	{
		frame(0, 0);

		frame(-2000, 0, false, false, true);

		assertEquals((1000 - 2000) & 0x3FFF, yaw);
	}

	@Test
	public void theCompassAlsoWorksWhileTheCameraIsRotated()
	{
		frame(0, 0.5);

		frame(-2000, 0.5, false, true, true);

		assertEquals((1000 - 2000) & 0x3FFF, yaw);
	}

	@Test
	public void afterTheCompassTheKeysAreScaledAgain()
	{
		frame(0, 0.4);
		frame(-2000, 0.4, false, false, true);

		int compassTarget = yaw;
		frame(24, 0.4);

		assertEquals(compassTarget + 9, yaw);
	}

	@Test
	public void theCompassLeavesThePitchToTheCameraKeys()
	{
		frame(0, 0.5);

		int before = pitch;

		pitch += 48;
		speed.update(yaw, pitch, 0.5, false, false, true);
		pitch = speed.pitch();

		assertEquals(before + 24, pitch);
	}

	@Test
	public void theYawWrapsAroundTheCircle()
	{
		yaw = 16380;
		frame(0, 1);

		frame(24, 1);

		assertEquals(16380 + 24 - 16384, yaw);
	}

	/** One frame in which the client moved the camera pitch by {@code movement}. */
	private void pitchFrame(int movement, double scale)
	{
		pitch += movement;
		speed.update(yaw, pitch, scale, false, false, false);
		yaw = speed.yaw();
		pitch = speed.pitch();
	}

	@Test
	public void thePitchStaysInsideTheClientLimits()
	{
		pitch = 3060;
		pitchFrame(0, 1);
		pitchFrame(24, 1);

		assertEquals(3064, pitch);
	}
}

